	fmt.Fprintf(out, "plugin state: %s\n", dirs.State)
	fmt.Fprintf(out, "plugin cache: %s\n", dirs.Cache)

	cfg, err := config.Load(dirs.Config)
	if err != nil {
		return err
	}
	fmt.Fprintf(out, "greeting: %s\n", cfg.Greeting)
