+func gitScalar(ctx context.Context, runner CommandRunner, repoDir string, args ...string) (string, error) {
+	stdout, _, err := runner.Run(ctx, repoDir, "git", args...)
+	if err != nil {
+		return "", err
+	}
+	return strings.TrimSpace(string(stdout)), nil
+}
