+			if opts.Env.RepoRoot != "" {
+				target = opts.Env.RepoRoot
+			}
+			if len(args) == 1 {
+				target = args[0]
+			}
+			return runSemanticGC(cmd.Context(), cmd, opts, target, olderThan)
+		},
+	}
