	if err != nil {
		return nil, fmt.Errorf("semantic provider snapshot failed: %w", err)
	}
	if len(bytes.TrimSpace(stdout)) == 0 {
		return nil, errors.New("semantic provider snapshot produced no output")
	}
	return stdout, nil
