func findSemanticRelationsForSymbolsInSQLite(storePath string, symbols []semanticRecord, limit int) ([]semanticRecord, error) {
	if len(symbols) == 0 {
		return nil, nil
	}
	ids := make([]any, 0, len(symbols)*2)
