	args = append(args, limit)
	inClause := strings.Join(placeholders, ",")
	rows, err := db.Query(`SELECT from_id, to_id, type, confidence, reason FROM relations
WHERE from_id IN (`+inClause+`) OR to_id IN (`+inClause+`)
