+	result := make([]string, 0, len(patterns))
+	seen := map[string]struct{}{}
+	for _, pattern := range patterns {
+		if _, ok := seen[pattern]; ok {
+			continue
+		}
+		seen[pattern] = struct{}{}
+		result = append(result, ":(exclude)"+pattern)
+	}
+	return result
+}

