func runStatus(cmd *cobra.Command, opts Options) error {
	out := cmd.OutOrStdout()
	fmt.Fprintln(out, "entire-brain")
	fmt.Fprintf(out, "version: %s\n", opts.Version)
	fmt.Fprintf(out, "entire cli: %s\n", valueOrUnset(opts.Env.CLIVersion))
